<template>
  <q-select
    outlined
    class="q-mr-sm"
    style="width: 227px; height: 40px"
    clearable
    dense
    v-model="selected_doc_type"
    @filter="filterlistEvent"
    :options="filtered_document_type_list"
    @update:model-value="modelUpdated"
    :label="$t('doc_type')"
    data-cy="doc_type"
  >
  <template v-slot:selected-item="scope">
    <div class="selected-item">{{scope.opt.label}}</div>
  </template>
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import docTypeLable from 'src/utils/docTypeLable';
import { useDocumentTypeFiltersStore } from 'src/store/main';
import { useFullSearchStore } from 'src/store/full-search.store';

export default defineComponent({
  mixins: [ docTypeLable],
  watch: {
    document_type_filter_loading: {
      handler: function (newVal, oldVal) {
        this.filtered_document_type_list = this.document_type_filter;
      },
    },
    tempFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadSavedFilter();
      },
    }
  },
  mounted() {
    this.getDocumentTypeFilters();
    this.loadSavedFilter();
  },

  methods: {
    resetFilters() {
      this.selected_doc_type = null;
      this.tempFilterMap.delete('doc_type');
    },

    loadSavedFilter() {
      const doc_type = this.tempFilterMap.get('doc_type');
      if (!doc_type) {
        this.selected_doc_type = null;
        return;
      }
      doc_type.label = this.getDocTypeLabel(doc_type)
      this.selected_doc_type = doc_type;
    },

    modelUpdated() {
      if (this.handleEmptyStatus()) {
        return;
      }

      this.tempFilterMap.set('doc_type', this.selected_doc_type);
    },

    handleEmptyStatus () {
      if (this.selected_doc_type && this.selected_doc_type !== null) {
        return false;
      }

      this.resetFilters();
      return true;
    },

    filterlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filtered_document_type_list = this.document_type_filter;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filtered_document_type_list = this.document_type_filter.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1
        );
      });
    },
  },
  setup() {
    const document_type_filter_store = useDocumentTypeFiltersStore();
    const { document_type_filter, document_type_filter_loading } = storeToRefs(document_type_filter_store);
    const { getDocumentTypeFilters } = document_type_filter_store;

    const full_search_store = useFullSearchStore();
    const { tempFilterMap } = storeToRefs(full_search_store);

    return {
     getDocumentTypeFilters,
     document_type_filter,
     document_type_filter_loading,
     filtered_document_type_list: ref([] as any),
     selected_doc_type: ref(null),
     tempFilterMap,
    };
  },
});
</script>
<style lang="scss">
.select-box.doc-type-select {
  max-width: 260px;
}

.selected-item {
  width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
</style>