<template>
  <div class="search-type-filter">
    <!-- Search Type Toggle -->
    <q-btn-toggle
      v-model="selected_search_type"
      toggle-color="primary"
      class="toggle-search-type dashboard-text-color back-white"
      :options="search_type_options"
      @update:model-value="modelUpdated"
      data-cy="search-type-toggle"
    >
      <template v-for="option, index in search_type_options" :key="index" #[index]>
        <q-tooltip>
          {{ option.tooltip }}
        </q-tooltip>
      </template>
    </q-btn-toggle>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue'
import { storeToRefs } from 'pinia'
import { useFullSearchStore, DEFAULT_SEARCH_TYPE } from 'src/store/full-search.store'

export default defineComponent({
  name: 'SearchTypeFilter',

  watch: {
    quickFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadSavedFilter()
      }
    }
  },

  mounted() {
    this.setSearchTypeOptions()
    this.loadSavedFilter()
  },

  methods: {
    setSearchTypeOptions() {
      this.search_type_options = [
        {
          label: this.$t('smart_ai_search'),
          value: 'vector',
          tooltip: this.$t('smart_ai_search_tooltip'),
          slot: 0
        },
        {
          label: this.$t('exact_match'),
          value: 'exact',
          tooltip: this.$t('exact_match_tooltip'),
          slot: 1
        },
        {
          label: this.$t('fuzzy'),
          value: 'fuzzy',
          tooltip: this.$t('fuzzy_match_tooltip'),
          slot: 2
        },
        {
          label: this.$t('prefix'),
          value: 'prefix',
          tooltip: this.$t('prefix_match_tooltip'),
          slot: 3
        }
      ]
    },

    loadSavedFilter() {
      const search_type = this.quickFilterMap.get('search_type')
      if (!search_type || !search_type.value) {
        this.selected_search_type = DEFAULT_SEARCH_TYPE // default to vector/smart AI search
        return
      }
      this.selected_search_type = search_type.value
    },

    modelUpdated() {
      // Update search type in quickFilterMap without triggering search
      this.quickFilterMap.set('search_type', {
        value: this.selected_search_type,
        label: this.selected_search_type
      })
    }
  },

  setup() {
    const full_search_store = useFullSearchStore()
    const { quickFilterMap, tempFilterMap } = storeToRefs(full_search_store)

    return {
      quickFilterMap,
      tempFilterMap,
      selected_search_type: ref(DEFAULT_SEARCH_TYPE),
      search_type_options: ref([] as any)
    }
  }
})
</script>

<style lang="scss" scoped>
.toggle-search-type {
  border: 1px solid rgba(0,0,0,0.04);
  background: white;
  border-radius: 8px;
  padding: 3px;
  height: auto !important;
  box-shadow: 0 1px 2px rgba(0,0,0,0.02);

  &.q-btn-group {
    box-shadow: none;
  }

  /* Target the individual buttons inside the toggle */
  :deep(.q-btn) {
    border-radius: 6px !important;
    font-size: 11px;
    font-weight: 600;
    margin: 0;
    min-height: 32px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 0 16px;
    white-space: nowrap;

    /* Inactive state opacity */
    &:not(.bg-primary) {
      color: #666;
      opacity: 0.8;
      &:hover {
        background: rgba(0,0,0,0.03);
        opacity: 1;
      }
    }
  }
}
</style>
