<template>
  <div v-if="document" class="document-details-panel">
    <!-- Panel Header -->
    <div class="panel-header q-pa-md q-pb-sm">
      <div class="row items-center justify-between">
        <h6 class="q-my-none text-weight-bold">{{ $t('document_details') }}</h6>
        <q-btn
          icon="close"
          flat
          round
          dense
          size="md"
          @click="closePanel"
        />
      </div>
    </div>

    <q-separator />

    <!-- Scrollable Content Area -->
    <q-scroll-area class="panel-content">
      <!-- View Section - Image Preview -->
      <q-expansion-item
        icon="image"
        :label="$t('view')"
        header-class="expansion-header"
        class="expansion-item view-section"
        default-opened
      >
        <!-- Image Container -->
        <div class="image-container">
          <div class="validate-container" v-if="document.image_path">
            <img
              class="document-thumbnail"
              :src="currentImagePath + '?' + tokenQueryParam"
              style="width: 100%; height: auto;"
              @load="onImageLoad"
            />
          </div>
          <div v-else class="no-image">
            No preview available
          </div>

          <!-- Page Navigation Controls (only show if multiple pages) -->
          <div v-if="totalPages > 1" class="page-navigation-controls">
            <q-btn
              icon="arrow_left"
              flat
              dense
              size="sm"
              :disable="currentPage === 1"
              @click="previousPage"
              class="nav-button"
            />
            <q-input
              v-model.number="currentPage"
              type="number"
              outlined
              dense
              :min="1"
              :max="totalPages"
              class="page-input"
              @update:model-value="goToPage"
              @blur="validatePageNumber"
            />
            <q-btn
              icon="arrow_right"
              flat
              dense
              size="sm"
              :disable="currentPage === totalPages"
              @click="nextPage"
              class="nav-button"
            />
          </div>
        </div>
      </q-expansion-item>

      <!-- Basic Information Section - All Metadata -->
      <q-expansion-item
        icon="info"
        :label="$t('basic_information')"
        header-class="expansion-header"
        class="expansion-item"
        default-opened
      >
        <div class="q-pa-md info-section">

          <!-- Title -->
          <div class="info-row" v-if="document.name">
            <span class="label">{{ $t('title') }}</span>
            <span class="value">{{ document.name }}</span>
          </div>

          <!-- Document Type -->
          <div class="info-row" v-if="document.doc_type">
            <span class="label">{{ $t('document_type') }}</span>
            <span class="value">{{ $t(document.doc_type.toLowerCase())}}</span> 
          </div>

          <!-- Sub Document Type 
          <div class="info-row" v-if="document.sub_doc_type">
            <span class="label">Sub document type</span>
             <span class="value">{{ displayDocType(document.sub_doc_key) }}</span>
          </div>
          -->

          <!-- Status -->
          <div class="info-row" v-if="document.status">
            <span class="label">{{ $t('doc_status') }}</span>
            <span class="value">
              <q-badge
                :class="getStatusClass(document.status)"
                align="middle"
              >
                {{ $t(document.status) }}
              </q-badge>
            </span>
          </div>

          <!-- PO Match Status -->
          <div class="info-row" v-if="document.po_match_status !== null && document.po_match_status !== undefined">
            <span class="label">{{ $t('po_match_status') }}</span>
            <span class="value">{{ $t(document.po_match_status) }}</span>
          </div>

          <!-- File Size -->
          <div class="info-row" v-if="document.file_size">
            <span class="label">{{ $t('file_size') }}</span>
            <span class="value">{{ document.file_size }}</span>
          </div>

          <!-- Pages -->
          <div class="info-row" v-if="document.pages !== null && document.pages !== undefined">
            <span class="label">{{ $t('page_number_text') }}</span>
            <span class="value">{{ document.pages }}</span>
          </div>

          <!-- Scanned Date/Time -->
          <div class="info-row" v-if="document.created_on">
            <span class="label">{{ $t('created_on') }}</span>
            <span class="value">{{ formatDateAccordingToPreference(document.created_on) }}</span>
          </div>

          <!-- Organization 
          <div class="info-row" v-if="document.sub_org_id">
            <span class="label">Organization</span>
            <span class="value">{{ getSubOrgName(document.sub_org_id) }}</span>
          </div>
          -->

          <!-- Document ID -->
          <div class="info-row" v-if="document.doc_id">
            <span class="label">{{ $t('document_id') }}</span>
            <span class="value text-caption">{{ document.doc_id }}</span>
          </div>
        </div>
      </q-expansion-item>

      <!-- Action Buttons -->
      <div class="q-pa-md view-document-button-container">
        <q-btn
          color="primary"
          label="View Full Document"
          @click="openFullDocument"
          class="full-width"
        />
        <q-btn
          color="secondary"
          :label="$t('find_similar')"
          icon="content_copy"
          outline
          @click="findSimilarDocuments"
          :loading="fullSearchStore.similarDocumentsLoading"
          class="full-width q-mt-sm"
        />
      </div>
    </q-scroll-area>

    <!-- Similar Documents Dialog -->
    <q-dialog v-model="showSimilarDialog" persistent>
      <q-card style="width: 700px; max-width: 90vw; max-height: 80vh;">
        <q-card-section class="row items-center q-pb-none">
          <div class="text-h6">{{ $t('similar_documents') }}</div>
          <q-space />
          <q-btn icon="close" flat round dense v-close-popup @click="closeSimilarDialog" />
        </q-card-section>

        <!-- Facet Summary Chips -->
        <q-card-section class="q-pt-sm q-pb-none" v-if="fullSearchStore.similarDocumentsFacets">
          <div class="row q-gutter-xs">
            <q-chip
              v-for="dt in fullSearchStore.similarDocumentsFacets.doc_types.slice(0, 5)"
              :key="dt.value"
              outline
              color="primary"
              size="sm"
            >
              {{ $t(dt.value.toLowerCase()) }}: {{ dt.count }}
