              v-for="doc in fullSearchStore.similarDocuments"
              :key="doc.doc_id"
              clickable
              @click="selectSimilarDocument(doc)"
            >
              <q-item-section avatar>
                <q-badge
                  :color="getSimilarityColor(doc.similarity_percent)"
                  text-color="white"
                  class="q-pa-xs"
                >
                  {{ doc.similarity_percent }}%
                </q-badge>
              </q-item-section>
              <q-item-section>
