</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue'
import { storeToRefs } from 'pinia'
import { useFullSearchStore, SimilarDocument } from 'src/store/full-search.store'
import { useAuthTokenStore } from 'src/store/main'
import { DOC2API_URL } from 'src/pages/APIs'
import dateUtils from 'src/utils/date'
import DashboardHelper from 'src/pages/Dashboard/DashboardHelper'
import { UserSubOrg } from 'src/utils/organization/sub_organization'
import FullSearchApiService from 'src/services/document/FullSearchApiService'

const fullSearchApiService = new FullSearchApiService()

export default defineComponent({
  name: 'DocumentDetailsPanel',
  mixins: [dateUtils, DashboardHelper],
  props: {
    document: {
      type: Object,
      required: true
    }
  },
  data() {
    return {
      baseUrl: DOC2API_URL,
      currentPage: 1,
      baseImagePath: '',
      showSimilarDialog: false,
    }
  },
  computed: {
    totalPages(): number {
      return this.document?.pages || 1
    },
    currentImagePath(): string {
      if (!this.baseImagePath) {
        return this.baseUrl + '/' + this.document.image_path
      }
      return this.baseUrl + '/' + this.baseImagePath + '/' + this.currentPage + '.png'
    }
  },
  watch: {
    document: {
      handler(newDocument: any) {
        // Reset to page 1 when document changes
        this.currentPage = 1
        // Extract base path from image_path
        // e.g., from "resource/image/754b3842-aa4d-4bb6-a21e-4c00616d3bb4/1.png"
        // we extract "resource/image/754b3842-aa4d-4bb6-a21e-4c00616d3bb4"
        if (newDocument?.image_path) {
          const parts = newDocument.image_path.split('/')
          // Remove the last part (page number and extension)
          parts.pop()
          this.baseImagePath = parts.join('/')
        }
      },
      immediate: true
    }
  },
  mounted() {
    this.prepareStatusList()
  },
  methods: {
    closePanel() {
      const store = useFullSearchStore()
      store.closeDetailsPanel()
    },
    onImageLoad(event: Event) {
      // Image loaded - no zoom logic needed for now
    },
    getSubOrgName(sub_org_id: string) {
      const subOrg = UserSubOrg.getSubOrgbyId(sub_org_id)
      return (subOrg?.name as string) || sub_org_id
    },
    previousPage() {
      if (this.currentPage > 1) {
        this.currentPage--
      }
    },
    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++
      }
    },
    goToPage(page: number) {
      // If empty or 0, set to 1
      if (!page || page === 0) {
        this.currentPage = 1
        return
      }

      // If exceeds total pages, cap to max page
      if (page > this.totalPages) {
        this.currentPage = this.totalPages
        return
      }

      // If negative, set to 1
      if (page < 1) {
        this.currentPage = 1
        return
      }

      // Valid page, set it
      this.currentPage = page
    },
    validatePageNumber() {
      // Ensure value is valid on blur
      if (!this.currentPage || this.currentPage === 0) {
        this.currentPage = 1
        return
      }

      if (this.currentPage > this.totalPages) {
        this.currentPage = this.totalPages
        return
      }

      if (this.currentPage < 1) {
        this.currentPage = 1
      }
    },
    openFullDocument() {
      // Navigate to document view page with the document ID
      if (this.document?.doc_id) {
        this.$router.push('/document/' + this.document.doc_id)
      }
    },
    openDocument(docId: string) {
      // Navigate to document view page
      this.$router.push('/document/' + docId)
    },
    async findSimilarDocuments() {
      if (!this.document?.doc_id) return

      const store = useFullSearchStore()
      store.setSimilarDocumentsLoading(true)

      try {
        const response = await fullSearchApiService.getSimilarDocuments(
          this.document.doc_id,
          15,  // k = 15 similar documents
          false  // don't exclude same doc type
        )

        if (response?.success) {
          store.setSimilarDocuments(
            response.documents || [],
            response.facets || null,
            this.document.doc_id
          )
          this.showSimilarDialog = true
        } else {
          notify.error(response?.message || 'Failed to find similar documents')
        }
      } catch (error: any) {
        console.error('Error finding similar documents:', error)
        notify.error(error?.message || 'Error finding similar documents')
      } finally {
        store.setSimilarDocumentsLoading(false)
      }
    },
    closeSimilarDialog() {
      this.showSimilarDialog = false
      const store = useFullSearchStore()
      store.closeSimilarPanel()
    },
    selectSimilarDocument(doc: SimilarDocument) {
      // Close the dialog and select the document in the details panel
      this.showSimilarDialog = false
      const store = useFullSearchStore()
      store.closeSimilarPanel()
      store.selectDocument(doc)
    },
    getSimilarityColor(percent: number): string {
      if (percent >= 80) return 'positive'
      if (percent >= 60) return 'primary'
      if (percent >= 40) return 'warning'
      return 'grey'
    },
    formatAmount(amount: number): string {
      if (amount === null || amount === undefined) return ''
      return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: 2
      }).format(amount)
    }
  },
  setup() {
    const auth_store = useAuthTokenStore()
    const { tokenQueryParam } = storeToRefs(auth_store)
    const fullSearchStore = useFullSearchStore()

    return {
      tokenQueryParam,
      fullSearchStore
    }
  }
})
</script>

