<template>
  <q-menu
    style="width: 450px; min-height: 250px"
    anchor="bottom left"
    self="top left"
    :offset="[398, 10]"
    @show="onFilterShow"
  >
    <div class="q-pa-md">
      <!-- Document Type Filter -->
      <div class="row q-my-sm capitalize">
        <span style="margin-top: 10px">{{$t('doc_type')}}</span>
        <q-space />
        <DocTypeFilter />
      </div>

      <!-- Status Filter -->
      <div class="row q-my-sm capitalize">
        <span style="margin-top: 10px">{{$t('status')}}</span>
        <q-space />
        <StatusFilter />
      </div>

      <!-- Action Buttons -->
      <div class="float-right q-ml-auto">
        <f-btn
          class="q-mr-sm mt-20 q-mb-md text-uppercase"
          appearance="negative-tertiary"
          :label="$t('clear_filters')"
          data-cy="clear-filters-btn"
          @click="handleClear"
        />
        <f-btn
          class="q-mr-sm mt-20 q-mb-md text-uppercase"
          :label="$t('apply')"
          data-cy="apply-filters-btn"
          @click="handleApply"
          v-close-popup
        />
      </div>
    </div>
  </q-menu>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import StatusFilter from './filters/status-filter.vue';
import DocTypeFilter from './filters/doc_type-filter.vue';
import { useFullSearchStore } from 'src/store/full-search.store';
import { storeToRefs } from 'pinia';

export default defineComponent({
  name: 'SearchFilterMenu',
  components: {
    StatusFilter,
    DocTypeFilter
  },
  methods: {
    /**
     * Called when filter menu opens
     * Copy quick filters to temp filters for editing
     */
    onFilterShow() {
      this.tempFilterMap = new Map(this.quickFilterMap);
    },

    /**
     * Handle Apply button click
     * Copy temp filters back to quick filters and trigger search
     */
    handleApply() {
      this.quickFilterMap = new Map(this.tempFilterMap);
      this.triggerApplyFilters();
    },

    /**
     * Handle Clear button click
     * Clear all filters and trigger search
     */
    handleClear() {
      this.quickFilterMap.clear();
      this.tempFilterMap.clear();
      this.triggerResetFilters();
      // Also trigger search with no filters
      this.triggerApplyFilters();
    },

    /**
     * Trigger apply filters event
     */
    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },

    /**
     * Trigger reset filters event
     */
    triggerResetFilters() {
      const event = new CustomEvent('reset_filters', { detail: {} });
      document.dispatchEvent(event);
    }
  },
  setup() {
    const full_search_store = useFullSearchStore();
    const { tempFilterMap, quickFilterMap } = storeToRefs(full_search_store);

    return {
      tempFilterMap,
      quickFilterMap
    };
  }
});
</script>
