import { defineStore } from 'pinia'
import { CONSTANTS } from 'src/constants'

// Default search type - vector search provides best UX for business users
export const DEFAULT_SEARCH_TYPE = 'vector'

// Facet interfaces
export interface FacetItem {
  value: string
  count: number
}

export interface AmountRange {
  key: string
  from?: number
  to?: number
  count: number
}

export interface AmountStats {
  count: number
  min: number | null
  max: number | null
  avg: number | null
  sum: number | null
}

export interface SearchFacets {
  doc_types: FacetItem[]
  statuses: FacetItem[]
  vendors: FacetItem[]
  po_match_statuses: FacetItem[]
  amount_ranges: AmountRange[]
  amount_stats: AmountStats
  total: number
}

export interface SearchSuggestion {
  value: string
  count: number
}

export interface SearchSuggestions {
  vendors: SearchSuggestion[]
  filenames: SearchSuggestion[]
  invoice_numbers: SearchSuggestion[]
}

export interface SimilarDocument {
  doc_id: string
  name: string
  created_on: string
  doc_type: string
  sub_doc_type?: string
  sub_org_id?: string
  status: string
  po_match_status?: string
  file_size?: string
  pages?: number
  image_path?: string
  similarity_score: number
  similarity_percent: number
  vendor_name?: string
  total_amount?: number
}

export const useFullSearchStore = defineStore('fullSearch', {
  state: () => ({
    // Active filters
    quickFilterMap: new Map<string, any>(),
    // Temporary filters (before applying)
    tempFilterMap: new Map<string, any>(),
    // Document details panel
    selectedDocument: null as any,
    detailsPanelOpen: false,

    // Faceted search state
    facets: null as SearchFacets | null,
    facetsLoading: false,

    // Autocomplete suggestions state
    suggestions: null as SearchSuggestions | null,
    suggestionsLoading: false,

    // Business filter state
    selectedVendors: [] as string[],
    amountRange: {
      min: null as number | null,
      max: null as number | null
    },
    selectedPoMatchStatuses: [] as string[],

    // Similar documents state
    similarDocuments: [] as SimilarDocument[],
    similarDocumentsFacets: null as SearchFacets | null,
    similarDocumentsLoading: false,
    showSimilarPanel: false,
    similarSourceDocId: null as string | null,
  }),

  getters: {
    // Get search type from filter map, defaulting to vector search
    searchType(): string {
      const searchType = this.quickFilterMap.get('search_type')
      return searchType?.value || DEFAULT_SEARCH_TYPE
    },

    // Check if any business filters are active
    hasActiveBusinessFilters(): boolean {
      return (
        this.selectedVendors.length > 0 ||
        this.amountRange.min !== null ||
        this.amountRange.max !== null ||
        this.selectedPoMatchStatuses.length > 0
      )
    }
  },

  actions: {
    setQuickFilterMap(filterMap: Map<string, any>) {
      this.quickFilterMap = filterMap
    },

    setTempFilterMap(filterMap: Map<string, any>) {
      this.tempFilterMap = filterMap
    },

    clearAllFilters() {
      this.quickFilterMap.clear()
      this.tempFilterMap.clear()
      // Clear business filters
      this.selectedVendors = []
      this.amountRange = { min: null, max: null }
      this.selectedPoMatchStatuses = []
    },

    saveFilters() {
      // Save filters to localStorage
      const filterArray = Array.from(this.quickFilterMap.entries())
      localStorage.setItem(CONSTANTS.full_search_filters, JSON.stringify(filterArray))
    },

    selectDocument(document: any) {
      this.selectedDocument = document
      this.detailsPanelOpen = true
    },

    closeDetailsPanel() {
      this.detailsPanelOpen = false
      this.selectedDocument = null
    },

    deselectDocument() {
      this.closeDetailsPanel()
    },

    // Facet management
    setFacets(facets: SearchFacets) {
      this.facets = facets
    },

    setFacetsLoading(loading: boolean) {
      this.facetsLoading = loading
    },

    // Suggestion management
    setSuggestions(suggestions: SearchSuggestions) {
      this.suggestions = suggestions
    },

    setSuggestionsLoading(loading: boolean) {
      this.suggestionsLoading = loading
    },

    clearSuggestions() {
      this.suggestions = null
    },

    // Business filter management
    setSelectedVendors(vendors: string[]) {
      this.selectedVendors = vendors
    },

    toggleVendor(vendor: string) {
      const index = this.selectedVendors.indexOf(vendor)
      if (index > -1) {
        this.selectedVendors.splice(index, 1)
      } else {
        this.selectedVendors.push(vendor)
      }
    },

    setAmountRange(min: number | null, max: number | null) {
      this.amountRange = { min, max }
    },

    setSelectedPoMatchStatuses(statuses: string[]) {
      this.selectedPoMatchStatuses = statuses
    },

    togglePoMatchStatus(status: string) {
      const index = this.selectedPoMatchStatuses.indexOf(status)
      if (index > -1) {
        this.selectedPoMatchStatuses.splice(index, 1)
      } else {
        this.selectedPoMatchStatuses.push(status)
      }
    },

    // Similar documents management
    setSimilarDocuments(documents: SimilarDocument[], facets: SearchFacets, sourceDocId: string) {
      this.similarDocuments = documents
      this.similarDocumentsFacets = facets
      this.similarSourceDocId = sourceDocId
      this.showSimilarPanel = true
    },

    setSimilarDocumentsLoading(loading: boolean) {
      this.similarDocumentsLoading = loading
    },

    closeSimilarPanel() {
      this.showSimilarPanel = false
      this.similarDocuments = []
      this.similarDocumentsFacets = null
      this.similarSourceDocId = null
    },

    clearSimilarDocuments() {
      this.similarDocuments = []
      this.similarDocumentsFacets = null
      this.similarSourceDocId = null
    },
  },
})
