<template>
  <div class="search-autocomplete" ref="autocompleteRef">
    <q-input
      v-model="searchQuery"
      :placeholder="$t('search_placeholder_hints')"
      outlined
      dense
      clearable
      @update:model-value="onInputChange"
      @keydown="onKeydown"
      @focus="onFocus"
      @blur="onBlur"
      @clear="onClear"
      data-cy="search-autocomplete-input"
    >
      <template v-slot:prepend>
        <q-icon name="search" />
      </template>
      <template v-slot:append>
        <q-spinner v-if="suggestionsLoading" size="sm" color="primary" />
      </template>
    </q-input>

    <!-- Suggestions Dropdown -->
    <div
      v-if="showSuggestions && hasSuggestions"
      class="suggestions-dropdown"
      data-cy="suggestions-dropdown"
    >
      <!-- Vendors Section -->
      <div v-if="suggestions?.vendors?.length > 0" class="suggestion-group">
        <div class="suggestion-group-header">
          <q-icon name="business" size="xs" class="q-mr-xs" />
          {{ $t('vendors') }}
        </div>
        <q-item
          v-for="(item, index) in suggestions.vendors"
          :key="'vendor-' + index"
          clickable
          dense
          :class="{ 'suggestion-highlighted': highlightedIndex === getGlobalIndex('vendors', index) }"
          @click="selectSuggestion(item.value, 'vendor')"
          @mouseenter="highlightedIndex = getGlobalIndex('vendors', index)"
        >
          <q-item-section>
            <q-item-label v-html="highlightMatch(item.value)" />
          </q-item-section>
          <q-item-section side>
            <q-badge color="grey-5" text-color="dark">{{ item.count }}</q-badge>
          </q-item-section>
        </q-item>
      </div>

      <!-- Filenames Section -->
      <div v-if="suggestions?.filenames?.length > 0" class="suggestion-group">
        <div class="suggestion-group-header">
          <q-icon name="description" size="xs" class="q-mr-xs" />
          {{ $t('filenames') }}
        </div>
        <q-item
          v-for="(item, index) in suggestions.filenames"
          :key="'filename-' + index"
          clickable
          dense
          :class="{ 'suggestion-highlighted': highlightedIndex === getGlobalIndex('filenames', index) }"
          @click="selectSuggestion(item.value, 'filename')"
          @mouseenter="highlightedIndex = getGlobalIndex('filenames', index)"
        >
          <q-item-section>
            <q-item-label v-html="highlightMatch(item.value)" />
          </q-item-section>
          <q-item-section side>
            <q-badge color="grey-5" text-color="dark">{{ item.count }}</q-badge>
          </q-item-section>
        </q-item>
      </div>

      <!-- Invoice Numbers Section -->
      <div v-if="suggestions?.invoice_numbers?.length > 0" class="suggestion-group">
        <div class="suggestion-group-header">
          <q-icon name="receipt" size="xs" class="q-mr-xs" />
          {{ $t('invoice_numbers') }}
        </div>
        <q-item
          v-for="(item, index) in suggestions.invoice_numbers"
          :key="'invoice-' + index"
          clickable
          dense
          :class="{ 'suggestion-highlighted': highlightedIndex === getGlobalIndex('invoice_numbers', index) }"
          @click="selectSuggestion(item.value, 'invoice_number')"
          @mouseenter="highlightedIndex = getGlobalIndex('invoice_numbers', index)"
        >
          <q-item-section>
            <q-item-label v-html="highlightMatch(item.value)" />
          </q-item-section>
          <q-item-section side>
            <q-badge color="grey-5" text-color="dark">{{ item.count }}</q-badge>
          </q-item-section>
        </q-item>
      </div>

      <!-- No Results -->
      <div v-if="!hasSuggestions && searchQuery.length >= 2" class="no-suggestions">
        {{ $t('no_suggestions_found') }}
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch, onMounted, onUnmounted } from 'vue'
import { storeToRefs } from 'pinia'
import { useFullSearchStore, type SearchSuggestions } from 'src/store/full-search.store'
import { fullSearchApiService } from 'src/services'
import { getOrgId } from 'src/utils/organization/org_id_helper'
import { debounce } from 'quasar'

export default defineComponent({
  name: 'SearchAutocomplete',

  props: {
    modelValue: {
      type: String,
      default: ''
    }
  },

  emits: ['update:modelValue', 'search', 'suggestion-selected'],

  setup(props, { emit }) {
    const fullSearchStore = useFullSearchStore()
    const { suggestions, suggestionsLoading } = storeToRefs(fullSearchStore)

    const autocompleteRef = ref<HTMLElement | null>(null)
    const searchQuery = ref(props.modelValue)
    const showSuggestions = ref(false)
    const highlightedIndex = ref(-1)
    const isFocused = ref(false)


    // Sync with parent model
    watch(() => props.modelValue, (newVal) => {
      searchQuery.value = newVal
    })

    // Computed
    const hasSuggestions = computed(() => {
      if (!suggestions.value) return false
      return (
        (suggestions.value.vendors?.length || 0) > 0 ||
        (suggestions.value.filenames?.length || 0) > 0 ||
        (suggestions.value.invoice_numbers?.length || 0) > 0
      )
    })

    const totalSuggestions = computed(() => {
      if (!suggestions.value) return 0
      return (
        (suggestions.value.vendors?.length || 0) +
        (suggestions.value.filenames?.length || 0) +
        (suggestions.value.invoice_numbers?.length || 0)
      )
    })

    // Get global index for keyboard navigation
    const getGlobalIndex = (group: string, localIndex: number): number => {
      if (!suggestions.value) return -1
      let offset = 0
      if (group === 'vendors') {
        return localIndex
      }
      offset += suggestions.value.vendors?.length || 0
      if (group === 'filenames') {
        return offset + localIndex
      }
      offset += suggestions.value.filenames?.length || 0
      if (group === 'invoice_numbers') {
        return offset + localIndex
      }
      return -1
    }

    // Get suggestion by global index
    const getSuggestionByIndex = (index: number): { value: string; type: string } | null => {
      if (!suggestions.value || index < 0) return null

      const vendorsLen = suggestions.value.vendors?.length || 0
      const filenamesLen = suggestions.value.filenames?.length || 0

      if (index < vendorsLen) {
        return { value: suggestions.value.vendors[index].value, type: 'vendor' }
      }
      if (index < vendorsLen + filenamesLen) {
        return { value: suggestions.value.filenames[index - vendorsLen].value, type: 'filename' }
      }
      const invoiceIndex = index - vendorsLen - filenamesLen
      if (invoiceIndex < (suggestions.value.invoice_numbers?.length || 0)) {
        return { value: suggestions.value.invoice_numbers[invoiceIndex].value, type: 'invoice_number' }
      }
      return null
    }

    // Fetch suggestions with debounce
    const fetchSuggestions = debounce(async (query: string) => {
      if (query.length < 2) {
        fullSearchStore.clearSuggestions()
        return
      }

      fullSearchStore.setSuggestionsLoading(true)
      try {
        const formData = new FormData()
        formData.append('org_id', getOrgId())
        formData.append('query', query)
        formData.append('limit', '5')

        const response = await fullSearchApiService.getSearchSuggestions(formData)
        if (response.data) {
          fullSearchStore.setSuggestions(response.data)
        }
      } catch (error) {
        console.error('Failed to fetch suggestions:', error)
        fullSearchStore.clearSuggestions()
      } finally {
        fullSearchStore.setSuggestionsLoading(false)
      }
    }, 300)

    // Event handlers
    const onInputChange = (value: string | number | null) => {
      const strValue = value?.toString() || ''
      emit('update:modelValue', strValue)
      if (strValue.length >= 2) {
        showSuggestions.value = true
        fetchSuggestions(strValue)
      } else {
        showSuggestions.value = false
        fullSearchStore.clearSuggestions()
      }
      highlightedIndex.value = -1
    }

    const onKeydown = (event: KeyboardEvent) => {
      if (!showSuggestions.value || !hasSuggestions.value) {
        if (event.key === 'Enter') {
          emit('search', searchQuery.value)
        }
        return
      }

      switch (event.key) {
        case 'ArrowDown':
          event.preventDefault()
          highlightedIndex.value = Math.min(highlightedIndex.value + 1, totalSuggestions.value - 1)
          break
        case 'ArrowUp':
          event.preventDefault()
          highlightedIndex.value = Math.max(highlightedIndex.value - 1, -1)
          break
        case 'Enter':
          event.preventDefault()
          if (highlightedIndex.value >= 0) {
            const suggestion = getSuggestionByIndex(highlightedIndex.value)
            if (suggestion) {
              selectSuggestion(suggestion.value, suggestion.type)
            }
          } else {
            emit('search', searchQuery.value)
            showSuggestions.value = false
          }
          break
        case 'Escape':
          showSuggestions.value = false
          highlightedIndex.value = -1
          break
      }
    }

    const onFocus = () => {
      isFocused.value = true
      if (searchQuery.value.length >= 2 && hasSuggestions.value) {
        showSuggestions.value = true
      }
    }

    const onBlur = () => {
      // Delay to allow click events on suggestions
      setTimeout(() => {
        isFocused.value = false
        showSuggestions.value = false
      }, 200)
    }

    const onClear = () => {
      searchQuery.value = ''
      emit('update:modelValue', '')
      fullSearchStore.clearSuggestions()
      showSuggestions.value = false
    }

    const selectSuggestion = (value: string, type: string) => {
      searchQuery.value = value
      emit('update:modelValue', value)
      emit('suggestion-selected', { value, type })
      showSuggestions.value = false
      highlightedIndex.value = -1
    }

    const highlightMatch = (text: string): string => {
      if (!searchQuery.value) return text
      const regex = new RegExp(`(${escapeRegExp(searchQuery.value)})`, 'gi')
      return text.replace(regex, '<strong>$1</strong>')
    }

    const escapeRegExp = (string: string): string => {
      return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    }

    // Click outside to close
    const handleClickOutside = (event: MouseEvent) => {
      if (autocompleteRef.value && !autocompleteRef.value.contains(event.target as Node)) {
        showSuggestions.value = false
      }
    }

    onMounted(() => {
      document.addEventListener('click', handleClickOutside)
    })

    onUnmounted(() => {
      document.removeEventListener('click', handleClickOutside)
    })

    return {
      autocompleteRef,
      searchQuery,
      suggestions,
      suggestionsLoading,
      showSuggestions,
      highlightedIndex,
      hasSuggestions,
      totalSuggestions,
      getGlobalIndex,
      onInputChange,
      onKeydown,
      onFocus,
      onBlur,
      onClear,
      selectSuggestion,
      highlightMatch
    }
  }
})
</script>

