<template>
  <div class="time-range-filter">
    <!-- Preset Time Range Toggle -->
    <q-btn-toggle
      toggle-color="primary"
      class="toggle-time dashboard-text-color back-white"
      v-model="selected_time"
      @click="timeFilterSelected"
      :ripple="false"
      :options="time_options"
      data-cy="time-range-toggle"
    >
      <template v-for="option, index in time_options" :key="index" #[index]>
        <q-tooltip>
          {{ option.tooltip }}
        </q-tooltip>
      </template>
    </q-btn-toggle>

    <!-- Custom Date Range Picker Menu -->
    <q-menu
      v-if="open_date_picker"
      @before-show="isCustomSelected"
      anchor="bottom right"
      self="top right"
      data-cy="date-range-menu"
    >
      <div class="q-pa-md">
        <date-range-filter
          :start_date="startDate"
          :end_date="endDate"
        />
        <f-btn
          class="q-mr-sm mt-10 float-right q-mb-md text-uppercase"
          :label="$t('apply')"
          @click="triggerApplyFilters()"
          v-close-popup
          data-cy="apply-date-range-btn"
        />
      </div>
    </q-menu>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue'
import { storeToRefs } from 'pinia'
import { useFullSearchStore } from 'src/store/full-search.store'
import { CONSTANTS } from 'src/constants'
import DateRangeFilter from './date-range-filter.vue'
export default defineComponent({
  name: 'TimeRangeFilter',
    components: {
    DateRangeFilter
  },

  data() {
    return {
      open_date_picker: false
    }
  },

  watch: {
    quickFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadFilters()
      }
    }
  },

  mounted() {
    this.setTimeOptions()
    this.loadFilters()

    // Set default if no filter is set
    if (!this.selected_time) {
      this.selected_time = 'all'
    }

    document.addEventListener('clear_custom_dates', this.clearDates)
    document.addEventListener('reset_filters', this.handleResetFilters)
  },

  unmounted() {
    document.removeEventListener('clear_custom_dates', this.clearDates)
    document.removeEventListener('reset_filters', this.handleResetFilters)
  },

  methods: {
    handleResetFilters() {
      this.selected_time = 'all'
      this.clearDates()
      this.quickFilterMap.delete('filter')
      this.quickFilterMap.delete('date_range')
      this.tempFilterMap.delete('filter')
      this.tempFilterMap.delete('date_range')
    },

    isCustomSelected() {
      if (this.selected_time !== 'custom') {
        this.open_date_picker = false
      }
    },

    loadFilters() {
      // Check if custom date range is set
      if (this.quickFilterMap.has('date_range')) {
        this.selected_time = 'custom'
        const rangeStr = this.quickFilterMap.get('date_range')
        if (rangeStr) {
          try {
            // Parse JSON format: {"gte": "2024-01-01T00:00:00Z", "lte": "2024-12-31T23:59:59Z"}
            const rangeObj = JSON.parse(rangeStr)

            if (rangeObj.gte) {
              // Extract date part only (YYYY-MM-DD)
              this.startDate = rangeObj.gte.split('T')[0]
            }

            if (rangeObj.lte) {
              // Extract date part only (YYYY-MM-DD)
              this.endDate = rangeObj.lte.split('T')[0]
            }
          } catch (e) {
            // Fallback: try old format in case of parsing error
            const dates = rangeStr.split(CONSTANTS.dateSplitBy)
            if (dates[0] && dates[0] !== CONSTANTS.questionSymbol) {
              this.startDate = dates[0]
            }
            if (dates[1] && dates[1] !== CONSTANTS.questionSymbol) {
              this.endDate = dates[1]
            }
          }
        }
        return
      }

      // Check if preset filter is set
      const selected_time = this.quickFilterMap.get('filter')

      if (!selected_time || !selected_time.hasOwnProperty('value')) {
        this.resetFilters()
        return
      }

      this.selected_time = selected_time.value
    },

    resetFilters() {
      this.selected_time = 'all'
      this.clearDates()
    },

    timeFilterSelected() {
      // Clear custom date range if switching away from custom
      if (this.open_date_picker && this.selected_time !== 'custom') {
        this.tempFilterMap.delete('date_range')
        this.quickFilterMap.delete('date_range')
        this.open_date_picker = false
      }

      // Open date picker for custom range
      if (this.selected_time === 'custom') {
        this.open_date_picker = true
        return
      }

      // Show warning for heavy queries
      if (this.selected_time == 'last_365_days' || this.selected_time == 'all') {
        notify.warning(this.$t('may_increase_loading_time'))
      }

      // Store in both maps
      this.quickFilterMap.set('filter', {
        value: this.selected_time,
        label: this.selected_time
      })

      this.tempFilterMap.set('filter', {
        value: this.selected_time,
        label: this.selected_time
      })

      this.clearDates()
      this.triggerApplyFilters()
    },

    triggerApplyFilters() {
      // Check if custom date range is set in tempFilterMap
      if (this.tempFilterMap.has('date_range')) {
        // Apply custom date range
        this.quickFilterMap.set('date_range', this.tempFilterMap.get('date_range'))
        this.quickFilterMap.delete('filter')
        this.selected_time = 'custom'
      } else if (this.selected_time === 'custom') {
        // Both dates were cleared - switch to 'all' option
        this.selected_time = 'all'
        this.quickFilterMap.delete('date_range')
        this.quickFilterMap.set('filter', {
          value: 'all',
          label: 'all'
        })
        this.tempFilterMap.delete('date_range')
        // Also clear the component's internal state
        this.clearDates()
      }

      // Dispatch apply_filters event for FullSearch to handle
      const event = new CustomEvent('apply_filters', { detail: {} })
      document.dispatchEvent(event)
    },

    setTimeOptions() {
      this.time_options = [
        {
          label: this.$t('30_days'),
          value: 'last_30_days',
          tooltip: this.$t('last_30_days'),
          slot: 0
        },
        {
          label: this.$t('3_months'),
          value: 'last_90_days',
          tooltip: this.$t('last_90_days'),
          slot: 1
        },
        {
          label: this.$t('6_months'),
          value: 'last_180_days',
          tooltip: this.$t('last_180_days'),
          slot: 2
        },
        {
          label: this.$t('365_days'),
          value: 'last_365_days',
          tooltip: this.$t('last_365_days'),
          slot: 3
        },
        {
          label: this.$t('all'),
          value: 'all',
          tooltip: this.$t('all_time'),
          slot: 4
        },
        {
          label: this.$t('custom'),
          value: 'custom',
          tooltip: this.$t('select_date_range'),
          slot: 5
        }
      ]
    },

    clearDates() {
      this.startDate = ''
      this.endDate = ''
    }
  },

  setup() {
    const full_search_store = useFullSearchStore()
    const { quickFilterMap, tempFilterMap } = storeToRefs(full_search_store)

    return {
      quickFilterMap,
      tempFilterMap,
      selected_time: ref(''),
      time_options: ref([] as any),
      startDate: ref(''),
      endDate: ref('')
    }
  }
})
</script>

