<template>
  <q-select
    ref="q-select"
    class="q-mr-sm"
    dense
    style="width: 227px"
    multiple
    outlined
    use-input
    v-model="selected_status"
    @filter="filterlistEvent"
    @input="clearFilter"
    @update:model-value="modelUpdated"
    :options="filtered_status_list"
    :label="$t('status')"
    data-cy="status"
  >
    <template v-slot:option="{ itemProps, selected, opt, toggleOption}">
      <q-item v-bind="itemProps">
        <q-item-section side>
          <q-checkbox  :model-value="selected" @update:model-value="toggleOption(opt)"></q-checkbox>
        </q-item-section>
        <q-item-section>
          <div>{{ opt.label }}</div>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>


<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import documentUtil from 'src/utils/documentUtil';
import { status_filter_style_setting, status_filter_list, CONSTANTS} from 'src/constants';
import { useDocStatusDropdownStore, useSettingStore } from 'src/store/main';
import { useFullSearchStore } from 'src/store/full-search.store';

export default defineComponent({
  mixins: [documentUtil],
  watch: {
    status_list_loading: {
      handler: function (newVal, oldVal) {
        this.filtered_status_list = this.status_list;
      },
    },
    tempFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadSavedFilter();
      },
    }
  },
  data() {
    return {
      status_filter_style_setting,
    };
  },
  mounted() {
    
    if (!this.user_settings[this.status_filter_style_setting]) {
      this.user_settings[this.status_filter_style_setting] = CONSTANTS.all
    }

    let statusStr = this.user_settings[status_filter_list];

    if (statusStr && this.user_settings[this.status_filter_style_setting] == CONSTANTS.custom) {
      this.status_list = [];
      
      statusStr.split(',').forEach((item: any) => {
        let key = item;
        if (documentUtil.methods.getLabelTranslation(item) != '-') {
          this.status_list.push(Object.assign({},
            { value:key, label: documentUtil.methods.getLabelTranslation(item) }
          ));
        }
        this.filtered_status_list = this.status_list
      });
    } else {
      this.getStatusesList(this.user_settings[this.status_filter_style_setting]);
    }
    this.loadSavedFilter();
    document.addEventListener('quick_filter_remove', this.quickFilterRemove);
  },
  unmounted: function () {
    document.removeEventListener('quick_filter_remove', this.quickFilterRemove);
  },

  methods: {
    quickFilterRemove(e: any) {
      if (!e || !e.detail || e.detail !== 'status') {
        return;
      }
      this.selected_status = null;
      this.tempFilterMap.delete('status');

    },

    loadSavedFilter() {
      const status = this.tempFilterMap.get('status_list');
      if (!status) {
        this.selected_status = [];
        return;
      }
      status.forEach((item: any) =>{
        item.label = this.getLabelTranslation(item.value)
      });      
      this.selected_status = status;
    },

    modelUpdated() {

      if (this.handleEmptyStatus()) {
        return;
      }

      let status_str = ''
      if (this.selected_status.length > 0) {
        this.selected_status.forEach((status: any) => {
          status_str += status.value + ','
        })
        this.tempFilterMap.set('status', status_str);
        this.tempFilterMap.set('status_list', this.selected_status);
      } else {
        this.tempFilterMap.delete('status');
        this.tempFilterMap.delete('status_list');
      }
      this.tempFilterMap.delete('tab_status');

      this.triggerApplyFilters();
    },

    handleEmptyStatus () {
      if (this.selected_status && this.selected_status.length > 0) {
        return false;
      }

      this.quickFilterRemove({detail: 'status'});
      this.triggerApplyFilters();
      return true;
    },

    triggerApplyFilters () {
      const reset_event = new CustomEvent('reset_pages', {detail: { },});
      document.dispatchEvent(reset_event);
      // const event = new CustomEvent('apply_filters', {detail: { },});
      // document.dispatchEvent(event);
    },

    filterlistEvent(val: string, update: any) {
      if (!val) {
        update(() => {
          this.filtered_status_list = this.status_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filtered_status_list = this.status_list.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1
        );
      });
    },

    clearFilter () {
      if (this.$refs.qselect !== void 0) {
        (this.$refs.qselect as any).updateInputValue('')
      }
    }
  },
  setup() {
    const doc_status_dropdown = useDocStatusDropdownStore();
    const { status_list_loading, status_list } =
      storeToRefs(doc_status_dropdown);
    const { getStatusesList } = doc_status_dropdown;


    const full_search_store = useFullSearchStore();
    const { tempFilterMap } = storeToRefs(full_search_store);


    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      getStatusesList,
      status_list,
      tempFilterMap,
      status_list_loading,
      filtered_status_list: ref([] as any),
      selected_status: ref([] as any),
      user_settings,
    };
  },
});
</script>
<style lang="scss">
.select-box.status-select {
  width: 260px;
}
</style>
