  <div class="full-search-container">

    <!-- Main Content Area -->
    <div class="search-content">
      
      <!-- Search Header -->
      <div class="search-header">
        <!-- Row 1: Facet Toggle | Search | View Toggle -->
        <div class="search-header-row">
          <!-- Left: Facet Toggle -->
          <div class="search-header-left">
            <q-btn
              flat
              round
              size="md"
              :color="showFacetPanel ? 'primary' : undefined"
              :class="{ 'filter-btn-active': showFacetPanel }"
              class="filter-toggle-btn"
              @click="showFacetPanel = !showFacetPanel"
              data-cy="toggle-facets-btn"
              aria-label="Toggle filters"
            >
              <Icon :icon="showFacetPanel ? 'mdi:filter-off-outline' : 'mdi:filter-outline'" class="size-5" />
              <q-tooltip>{{ showFacetPanel ? $t('hide_filters') : $t('show_filters') }}</q-tooltip>
            </q-btn>
          </div>

          <!-- Center: Search Input -->
          <div class="search-header-center">
            <div class="search-input-container">
              <SearchAutocomplete
                v-model="search"
                @search="applySearch"
                @suggestion-selected="onSuggestionSelected"
                data-cy="search-autocomplete"
              />
              <q-btn
                flat
                round
                dense
                class="filter-menu-btn"
                :class="{ 'filter-menu-btn--active': showAdvancedFilters }"
                data-cy="filter-icon-btn"
                @click="showAdvancedFilters = !showAdvancedFilters"
                aria-label="Search options"
              >
                <Icon icon="mdi:tune-variant" class="size-5" />
                <q-tooltip>{{ showAdvancedFilters ? $t('hide_options') : $t('search_options') }}</q-tooltip>
              </q-btn>
            </div>
          </div>

          <!-- Right: View Toggle -->
          <div class="search-header-right">
            <div class="view-toggle-group">
              <q-btn
                flat
                dense
                :class="{ 'view-btn-active': viewMode === 'list' }"
                class="view-btn"
                @click="viewMode = 'list'"
                data-cy="list-view-btn"
                aria-label="List view"
              >
                <Icon icon="mdi:view-list" class="size-5" />
              </q-btn>
              <q-btn
                flat
                dense
                :class="{ 'view-btn-active': viewMode === 'grid' }"
                class="view-btn"
                @click="viewMode = 'grid'"
                data-cy="grid-view-btn"
                aria-label="Grid view"
              >
                <Icon icon="mdi:view-grid" class="size-5" />
              </q-btn>
            </div>
          </div>
        </div>

        <!-- Row 2: Advanced Filters (Collapsible) -->
        <q-slide-transition>
          <div v-show="showAdvancedFilters">
            <div class="advanced-filters-row">
              <time-range-filter data-cy="time-range-filter" />
              <search-type-filter data-cy="search-type-filter" />
            </div>
          </div>
        </q-slide-transition>
      </div>

      <!-- Documents Area with Facets and Details Panel -->
      <div class="documents-and-panel-container">
        <!-- Faceted Filter Panel (Left Sidebar) -->
        <div
          v-if="showFacetPanel"
          class="facet-panel-container"
        >
          <FacetedFilterPanel
            @filter-changed="debouncedFacetFilterChanged"
            data-cy="faceted-filter-panel"
          />
        </div>

        <!-- Documents View (Grid or List) -->
        <div
          class="documents-area"
          :class="{ 'panel-open': fullSearchStore.detailsPanelOpen, 'facet-open': showFacetPanel }"
        >
          <!--  Grid View -->
          <div v-if="viewMode === 'grid'" class="doc-grid">
            <div v-for="(doc, index) in documents" :key="index" class="col-1-10">
              <div class="doc-card" @click="onDocumentClick(doc)">
                <!-- Thumbnail Area -->
                <div class="doc-thumbnail-area">
                  <q-img
                    v-if="doc.image_path"
                    :src="baseUrl + '/' +  doc.image_path + '?' + tokenQueryParam"
                    class="doc-thumbnail"
                    fit="contain"
                    style="height: 100%; width: 100%;"
                  >
                    <template v-slot:loading>
                      <div class="doc-thumbnail-placeholder">
                        <Icon icon="mdi:image-outline" class="size-8" />
                      </div>
                    </template>
                    <template v-slot:error>
                      <div class="doc-thumbnail-placeholder">
                        <Icon icon="mdi:image-broken-variant" class="size-8" />
                      </div>
                    </template>
                  </q-img>
                  <div v-else class="doc-thumbnail-placeholder">
                    <Icon icon="mdi:file-document-outline" class="size-8" />
                  </div>
                </div>

                <!-- Info Area -->
                <div class="doc-info-section">
                  <div class="doc-title" :title="doc.name">
                    {{ doc.name }}
                  </div>
                  <div class="doc-meta">
                    <span class="doc-type-badge">{{ doc.doc_type }}</span>
                    <span class="doc-date-text">{{ formatDateAccordingToPreference(doc.created_on) }}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- 📜 List View (optional) -->
          <div v-else>
            <q-list bordered separator data-test="full-search-results-list">
              <q-item
                v-for="(doc, index) in documents"
                :key="index"
                clickable
                @click="onDocumentClick(doc)"
              >
              <!--
                <q-item-section avatar>
                  <q-checkbox v-model="doc.isSelected" dense />
                </q-item-section>
                -->
                <q-item-section>
                  <q-item-label class="text-primary ellipsify cursor-pointer">{{ doc.name }}</q-item-label>
                  <q-item-label caption>{{ doc.doc_type }} — {{ formatDateAccordingToPreference(doc.created_on) }}</q-item-label>
                </q-item-section>
              </q-item>
            </q-list>
          </div>
        </div>

        <!-- Document Details Panel (Inside same container) -->
        <div
          v-if="fullSearchStore.detailsPanelOpen"
          class="document-details-panel-container"
        >
          <DocumentDetailsPanel
            v-if="fullSearchStore.selectedDocument"
            :document="fullSearchStore.selectedDocument"
          />
        </div>
      </div>

      <!-- Pagination -->
      <div class="pagination-container">
        <q-pagination
          v-model="currentPage"
          color="primary"
          :max="Math.ceil(totalDocuments / pageSize)"
          :max-pages="6"
          input
          boundary-links
          @update:model-value="applySearch"
        />
      </div>
    </div>
  </div>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia'
import { defineComponent } from 'vue'
import { debounce } from 'quasar'
import dateUtils from 'src/utils/date'
import { DOC2API_URL } from 'src/pages/APIs'
import type { dynamicObj } from 'src/pages/assets'
import Loader from 'src/components/Loader.vue'
import helperMixin from 'src/mixins/helperMixin'
import { useAuthTokenStore } from 'src/store/main'
import { useFullSearchStore, DEFAULT_SEARCH_TYPE } from 'src/store/full-search.store'
import { fullSearchApiService } from 'src/services'
import { ApiExceptions } from 'src/exceptions/index'
import { Icon } from '@iconify/vue'
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue'
import SearchFilterMenu from './components/search-filter-menu.vue'
import TimeRangeFilter from './components/time-range-filter.vue'
import SearchTypeFilter from './components/filters/search-type-filter.vue'
import DocumentDetailsPanel from 'src/pages/FullSearch/components/DocumentDetailsPanel.vue'
import FacetedFilterPanel from './components/FacetedFilterPanel.vue'
import SearchAutocomplete from './components/SearchAutocomplete.vue'
export default defineComponent({
  name: 'DocumentGridView',
  mixins: [helperMixin, dateUtils ],
  components: {
    Icon,
    Loader,
    SubHeader,
    SearchFilterMenu,
    TimeRangeFilter,
    SearchTypeFilter,
    DocumentDetailsPanel,
    FacetedFilterPanel,
    SearchAutocomplete,
  },
  data() {
    return {
      search: '' as string,
      viewMode: 'grid' as 'grid' | 'list',
      documents: [] as any,
      pageSize: 20,
      currentPage: 1,
      totalDocuments: 0,
      baseUrl: DOC2API_URL,
      showFacetPanel: true,
      showAdvancedFilters: false,
      // Debounced version of onFacetFilterChanged to prevent rapid-fire API calls
      debouncedFacetFilterChanged: null as ReturnType<typeof debounce> | null,
    }
  },

  created() {
    // Create debounced version of onFacetFilterChanged
    this.debouncedFacetFilterChanged = debounce(this.onFacetFilterChanged, 300);
  },

  mounted() {
    // Close details panel by default when page loads
    this.fullSearchStore.closeDetailsPanel()
    this.init()
    // Listen for apply filters event from time filter and search filter menu
    document.addEventListener('apply_filters', this.onFacetFilterChanged)
    // Deep link: ensure filter panel is open via ?open=filter-panel
    if (this.$route.query.open === 'filter-panel') {
      this.$nextTick(() => {
        this.showFacetPanel = true;
      });
    }
  },

  unmounted() {
    // Clean up event listeners
    document.removeEventListener('apply_filters', this.onFacetFilterChanged)
  },

  methods: {

    init() {
      this.applySearch();
      this.loadFacets();
    },

    async loadFacets() {
      try {
        this.fullSearchStore.setFacetsLoading(true);

        let formdata = new FormData();

        // Add search query if provided
        if(this.search && this.search.trim()) {
          let searchType = DEFAULT_SEARCH_TYPE;
          if(this.quickFilterMap.has('search_type')) {
            const searchTypeValue = this.quickFilterMap.get('search_type')
            if(searchTypeValue && searchTypeValue.value) {
              searchType = searchTypeValue.value
            }
          }
          const searchJson = {'type': searchType, 'value': this.search.trim()};
          formdata.append('search', JSON.stringify(searchJson));
        }

        // Add filters from filter menu (same as applySearch)
        if(this.quickFilterMap.has('doc_type')) {
          const docType = this.quickFilterMap.get('doc_type');
          if(docType && docType.value) {
            formdata.append('doc_type', docType.value);
          }
        }

        if(this.quickFilterMap.has('status')) {
          const status = this.quickFilterMap.get('status');
          if(status) {
            formdata.append('status', status);
          }
        }

        // Add time range filter from store (same as applySearch)
        if(this.quickFilterMap.has('date_range')) {
          const dateRangeStr = this.quickFilterMap.get('date_range');
          if(dateRangeStr) {
            // Check if it's a custom date range (contains comma) or preset
            if(dateRangeStr.includes(',')) {
              // Custom date range: parse comma-separated dates
              const [startDate, endDate] = dateRangeStr.split(',');
              if(startDate) {
                formdata.append('start_date', startDate);
              }
              if(endDate) {
                formdata.append('end_date', endDate);
              }
            } else if(dateRangeStr !== 'all') {
              // Preset filter (but not 'all'): send as date_range parameter
              formdata.append('date_range', dateRangeStr);
            }
          }
        } else if(this.quickFilterMap.has('filter')) {
          const filterValue = this.quickFilterMap.get('filter');
          if(filterValue && filterValue.value) {
            const timeFilter = filterValue.value;
            if(timeFilter !== 'all') {
              formdata.append('date_range', timeFilter);
            }
          }
        }

        // Add business filters from store
        // Use JSON.stringify to preserve values containing commas (e.g., "RUIZ FOOD PRODUCTS, INC.")
        if(this.fullSearchStore.selectedVendors.length > 0) {
          formdata.append('vendor_name', JSON.stringify(this.fullSearchStore.selectedVendors));
        }
        if(this.fullSearchStore.amountRange.min !== null) {
          formdata.append('amount_min', this.fullSearchStore.amountRange.min.toString());
        }
        if(this.fullSearchStore.amountRange.max !== null) {
          formdata.append('amount_max', this.fullSearchStore.amountRange.max.toString());
        }
        if(this.fullSearchStore.selectedPoMatchStatuses.length > 0) {
          formdata.append('po_match_status', JSON.stringify(this.fullSearchStore.selectedPoMatchStatuses));
        }

        // Add is_deleted filter (same as search)
        formdata.append('is_deleted', 'false');

        const response = await fullSearchApiService.getSearchFacets(formdata);
        if(response.success && response.facets) {
          this.fullSearchStore.setFacets(response.facets);
        }
      } catch (err: any) {
        console.error('Failed to load facets:', err);
      } finally {
        this.fullSearchStore.setFacetsLoading(false);
      }
    },

    async onFacetFilterChanged() {
      // When facet filters change, reload search results and update facet counts
      // Wait for applySearch to complete before loading facets to prevent race conditions
      this.currentPage = 1;
      await this.applySearch();
      this.loadFacets();
    },

    onSuggestionSelected(suggestion: { value: string; type: string }) {
      // When a suggestion is selected, apply the search
      this.search = suggestion.value;
      this.currentPage = 1;
      this.applySearch();
    },

    onDocumentClick(doc: any) {
      // Open document details panel instead of navigating
      this.fullSearchStore.selectDocument(doc);
    },

    async applySearch() {
      try {
        this.showLoading();

        let formdata = new FormData();

        // Add search query with search type
        if(this.search && this.search.trim()) {
          // Get search type from store, defaulting to vector/smart AI search
          let searchType = DEFAULT_SEARCH_TYPE;
          if(this.quickFilterMap.has('search_type')) {
            const searchTypeValue = this.quickFilterMap.get('search_type')
            if(searchTypeValue && searchTypeValue.value) {
              searchType = searchTypeValue.value
            }
          }

          const searchJson = {'type': searchType, 'value': this.search.trim()};
          formdata.append('search', JSON.stringify(searchJson));
        }

        // Add filters from filter menu
        if(this.quickFilterMap.has('doc_type')) {
          const docType = this.quickFilterMap.get('doc_type');
          if(docType && docType.value) {
            formdata.append('doc_type', docType.value);
          }
        }

        if(this.quickFilterMap.has('status')) {
          const status = this.quickFilterMap.get('status');
          if(status) {
            formdata.append('status', status);
          }
        }

        // Add time range filter from store
        if(this.quickFilterMap.has('date_range')) {
          const dateRangeStr = this.quickFilterMap.get('date_range');
          if(dateRangeStr) {
            // Check if it's a custom date range (contains comma) or preset
            if(dateRangeStr.includes(',')) {
              // Custom date range: parse comma-separated dates
              const [startDate, endDate] = dateRangeStr.split(',');

              if(startDate) {
                formdata.append('start_date', startDate);
              }

              if(endDate) {
                formdata.append('end_date', endDate);
              }
            } else if(dateRangeStr !== 'all') {
              // Preset filter (but not 'all'): send as date_range parameter
              formdata.append('date_range', dateRangeStr);
            }
            // If 'all', don't send any date filter
          }
        } else if(this.quickFilterMap.has('filter')) {
          const filterValue = this.quickFilterMap.get('filter');
          if(filterValue && filterValue.value) {
            const timeFilter = filterValue.value;
            // Only send if not 'all'
            if(timeFilter !== 'all') {
              formdata.append('date_range', timeFilter);
            }
            // If 'all', don't send any date filter
          }
        }

        // Add business filters from store
        // Use JSON.stringify to preserve values containing commas (e.g., "RUIZ FOOD PRODUCTS, INC.")
        if(this.fullSearchStore.selectedVendors.length > 0) {
          formdata.append('vendor_name', JSON.stringify(this.fullSearchStore.selectedVendors));
        }
        if(this.fullSearchStore.amountRange.min !== null) {
          formdata.append('amount_min', this.fullSearchStore.amountRange.min.toString());
        }
        if(this.fullSearchStore.amountRange.max !== null) {
          formdata.append('amount_max', this.fullSearchStore.amountRange.max.toString());
        }
        if(this.fullSearchStore.selectedPoMatchStatuses.length > 0) {
          formdata.append('po_match_status', JSON.stringify(this.fullSearchStore.selectedPoMatchStatuses));
        }

        formdata.append('size', this.pageSize.toString());
        formdata.append('from_', ((this.currentPage - 1) * this.pageSize).toString());

        const response = await fullSearchApiService.getFullSearchDashboard(formdata);
        if(!response.success) {
          throw response;
        }
        this.documents = response.documents;
        this.totalDocuments = response.total;
        this.hideLoading();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },

  setup() {

    const auth_token_store = useAuthTokenStore();
    const { tokenQueryParam } = storeToRefs(auth_token_store);
    auth_token_store.getTokenQueryParam();

    const full_search_store = useFullSearchStore();
    const { quickFilterMap } = storeToRefs(full_search_store);

    return {
      tokenQueryParam,
      quickFilterMap,
      fullSearchStore: full_search_store,
    };
  },
})
</script>

