<template>
  <div class="faceted-filter-panel">
    <!-- Clear All (shown only when filters active) -->
    <div v-if="hasActiveFilters" class="panel-clear-row">
      <q-btn
        flat
        dense
        color="primary"
        :label="$t('clear_all')"
        size="sm"
        @click="clearAllFilters"
        data-cy="clear-filters-btn"
      />
    </div>

    <!-- Loading State -->
    <div v-if="facetsLoading" class="q-pa-md">
      <q-skeleton type="rect" height="150px" class="q-mb-md" />
      <q-skeleton type="rect" height="150px" class="q-mb-md" />
      <q-skeleton type="rect" height="100px" />
    </div>

    <!-- Facets Content -->
    <div v-else class="facets-content">
      <!-- Document Type Facet -->
      <q-expansion-item
        v-if="facets && facets.doc_types.length > 0"
        default-opened
        dense
        :label="$t('document_type')"
        header-class="facet-header"
        data-cy="doc-type-facet"
      >
        <q-list dense>
          <q-item
            v-for="item in facets.doc_types"
            :key="item.value"
            clickable
            @click="toggleDocTypeFilter(item.value)"
            :class="{ 'bg-blue-1': isDocTypeSelected(item.value) }"
          >
            <q-item-section avatar>
              <q-checkbox
                :model-value="isDocTypeSelected(item.value)"
                dense
                @update:model-value="toggleDocTypeFilter(item.value)"
              />
            </q-item-section>
            <q-item-section>
              <q-item-label>{{ formatDocTypeLabel(item.value) }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-badge color="grey-5" text-color="dark">{{ item.count }}</q-badge>
            </q-item-section>
          </q-item>
        </q-list>
      </q-expansion-item>

      <!-- Vendor Facet -->
      <q-expansion-item
        v-if="facets && facets.vendors.length > 0"
        default-opened
        dense
        :label="$t('vendor')"
        header-class="facet-header"
        data-cy="vendor-facet"
      >
        <div class="q-px-md q-pb-sm">
          <q-input
            v-model="vendorSearch"
            :placeholder="$t('search_vendors')"
            dense
            outlined
            clearable
            class="vendor-search-input"
          >
            <template v-slot:prepend>
              <q-icon name="search" size="xs" />
            </template>
          </q-input>
        </div>

        <q-list dense>
          <q-item
            v-for="item in visibleVendors"
            :key="item.value"
            clickable
            @click="toggleVendorFilter(item.value)"
            :class="{ 'bg-blue-1': isVendorSelected(item.value) }"
          >
            <q-item-section avatar>
              <q-checkbox
                :model-value="isVendorSelected(item.value)"
                dense
                @update:model-value="toggleVendorFilter(item.value)"
              />
            </q-item-section>
            <q-item-section>
              <q-item-label class="ellipsis">{{ item.value }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-badge color="grey-5" text-color="dark">{{ item.count }}</q-badge>
            </q-item-section>
          </q-item>
          <q-item v-if="!vendorSearch && facets.vendors.length > 5 && !showAllVendors">
            <q-btn
              flat
              dense
              color="primary"
              :label="$t('show_more') + ` (${facets.vendors.length - 5})`"
              @click="showAllVendors = true"
            />
          </q-item>
          <q-item v-if="!vendorSearch && showAllVendors && facets.vendors.length > 5">
            <q-btn
              flat
              dense
              color="primary"
              :label="$t('show_less')"
              @click="showAllVendors = false"
            />
          </q-item>
        </q-list>
      </q-expansion-item>

      <!-- Amount Range Facet -->
      <q-expansion-item
        v-if="facets && facets.amount_ranges.some(r => r.count > 0)"
        default-opened
        dense
        :label="$t('amount')"
        header-class="facet-header"
        data-cy="amount-facet"
      >
        <q-list dense>
          <q-item
            v-for="range in facets.amount_ranges.filter(r => r.count > 0 && (typeof r.from === 'number' || typeof r.to === 'number'))"
            :key="range.key"
            clickable
            @click="setAmountRange(range)"
            :class="{ 'bg-blue-1': isAmountRangeSelected(range) }"
          >
            <q-item-section avatar>
              <q-radio
                :model-value="selectedAmountRangeKey"
                :val="range.key"
                dense
                @update:model-value="setAmountRange(range)"
              />
            </q-item-section>
            <q-item-section>
              <q-item-label>{{ formatAmountRangeLabel(range) }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-badge color="grey-5" text-color="dark">{{ range.count }}</q-badge>
            </q-item-section>
          </q-item>
        </q-list>

        <!-- Custom Amount Range -->
        <div class="q-pa-sm">
          <div class="text-caption q-mb-xs">{{ $t('custom_range') }}</div>
          <div class="row q-gutter-sm">
            <q-input
              v-model.number="customAmountMin"
              type="number"
              dense
              outlined
              :placeholder="$t('min')"
              class="col"
              @change="applyCustomAmountRange"
            />
            <q-input
              v-model.number="customAmountMax"
              type="number"
              dense
              outlined
              :placeholder="$t('max')"
              class="col"
              @change="applyCustomAmountRange"
            />
          </div>
        </div>
      </q-expansion-item>

      <!-- Status Facet -->
      <q-expansion-item
        v-if="facets && facets.statuses.length > 0"
        default-opened
        dense
        :label="$t('status')"
        header-class="facet-header"
        data-cy="status-facet"
      >
        <q-list dense>
          <q-item
            v-for="item in facets.statuses"
            :key="item.value"
            clickable
            @click="toggleStatusFilter(item.value)"
            :class="{ 'bg-blue-1': isStatusSelected(item.value) }"
          >
            <q-item-section avatar>
              <q-checkbox
                :model-value="isStatusSelected(item.value)"
                dense
                @update:model-value="toggleStatusFilter(item.value)"
              />
            </q-item-section>
            <q-item-section>
              <q-item-label>{{ $t(item.value) || item.value }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-badge color="grey-5" text-color="dark">{{ item.count }}</q-badge>
            </q-item-section>
          </q-item>
        </q-list>
      </q-expansion-item>

      <!-- PO Match Status Facet -->
      <q-expansion-item
        v-if="facets && facets.po_match_statuses.length > 0"
        dense
        :label="$t('po_match_status')"
        header-class="facet-header"
        data-cy="po-match-status-facet"
      >
        <q-list dense>
          <q-item
            v-for="item in facets.po_match_statuses"
            :key="item.value"
            clickable
            @click="togglePoMatchStatusFilter(item.value)"
            :class="{ 'bg-blue-1': isPoMatchStatusSelected(item.value) }"
          >
            <q-item-section avatar>
              <q-checkbox
                :model-value="isPoMatchStatusSelected(item.value)"
                dense
                @update:model-value="togglePoMatchStatusFilter(item.value)"
              />
            </q-item-section>
            <q-item-section>
              <q-item-label>{{ $t(item.value) || item.value }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-badge color="grey-5" text-color="dark">{{ item.count }}</q-badge>
            </q-item-section>
          </q-item>
        </q-list>
      </q-expansion-item>

      <!-- No Facets Available -->
      <div v-if="!facets || allFacetsEmpty" class="q-pa-md text-center text-grey">
        {{ $t('no_filters_available') }}
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { useFullSearchStore, type AmountRange } from 'src/store/full-search.store'
import { i18n } from 'src/boot/i18n'

export default defineComponent({
  name: 'FacetedFilterPanel',

  emits: ['filter-changed'],

  setup(props, { emit }) {
    const fullSearchStore = useFullSearchStore()
    const {
      facets,
      facetsLoading,
      selectedVendors,
      amountRange,
      selectedPoMatchStatuses,
      quickFilterMap
    } = storeToRefs(fullSearchStore)

    const showAllVendors = ref(false)
    const vendorSearch = ref('')
    const customAmountMin = ref<number | null>(null)
    const customAmountMax = ref<number | null>(null)
    const selectedAmountRangeKey = ref<string | null>(null)

    /**
     * Helper function to extract filter value from either object or string format.
     * Handles data structure inconsistency where some filters are stored as objects
     * (e.g., {value: 'INVOICE', label: 'INVOICE'}) and others as plain strings.
     */
    const getFilterValue = (filter: any): string => {
      if (!filter) return ''
      if (typeof filter === 'string') return filter
      if (typeof filter === 'object' && filter.value !== undefined) return String(filter.value)
      return ''
    }

    // Computed properties
    const filteredVendors = computed(() => {
      if (!facets.value) return []
      if (!vendorSearch.value) return facets.value.vendors

      const search = vendorSearch.value.toLowerCase()
      return facets.value.vendors.filter(v =>
        v.value.toLowerCase().includes(search)
      )
    })

    const visibleVendors = computed(() => {
      const vendors = filteredVendors.value
      // If searching, show all matches. If not searching, respect showAllVendors toggle.
      if (vendorSearch.value) return vendors
      return showAllVendors.value
        ? vendors
        : vendors.slice(0, 5)
    })

    const allFacetsEmpty = computed(() => {
      if (!facets.value) return true
      return (
        facets.value.doc_types.length === 0 &&
        facets.value.vendors.length === 0 &&
        facets.value.statuses.length === 0 &&
        facets.value.po_match_statuses.length === 0 &&
        facets.value.amount_ranges.every(r => r.count === 0)
      )
    })

    const hasActiveFilters = computed(() => {
      const docTypeFilter = quickFilterMap.value.get('doc_type')
      const statusFilter = quickFilterMap.value.get('status')
      return (
        selectedVendors.value.length > 0 ||
        amountRange.value.min !== null ||
        amountRange.value.max !== null ||
        selectedPoMatchStatuses.value.length > 0 ||
        !!getFilterValue(docTypeFilter) ||
        !!getFilterValue(statusFilter)
      )
    })

    // Methods
    const isDocTypeSelected = (docType: string) => {
      const filter = quickFilterMap.value.get('doc_type')
      const filterValue = getFilterValue(filter)
      if (!filterValue) return false
      const values = filterValue.split(',')
      return values.includes(docType)
    }

    const toggleDocTypeFilter = (docType: string) => {
      const filter = quickFilterMap.value.get('doc_type')
      const filterValue = getFilterValue(filter)
      let values: string[] = []
      if (filterValue) {
        values = filterValue.split(',')
      }
      const index = values.indexOf(docType)
      if (index > -1) {
        values.splice(index, 1)
      } else {
        values.push(docType)
      }
      if (values.length > 0) {
        quickFilterMap.value.set('doc_type', { value: values.join(','), label: values.join(', ') })
      } else {
        quickFilterMap.value.delete('doc_type')
      }
      emit('filter-changed')
    }

    const isVendorSelected = (vendor: string) => {
      return selectedVendors.value.includes(vendor)
    }

    const toggleVendorFilter = (vendor: string) => {
      fullSearchStore.toggleVendor(vendor)
      emit('filter-changed')
    }

    const isStatusSelected = (status: string) => {
      const filter = quickFilterMap.value.get('status')
      const filterValue = getFilterValue(filter)
      if (!filterValue) return false
      const values = filterValue.split(',')
      return values.includes(status)
    }

    const toggleStatusFilter = (status: string) => {
      const filter = quickFilterMap.value.get('status')
      const filterValue = getFilterValue(filter)
      let values: string[] = []
      if (filterValue) {
        values = filterValue.split(',')
      }
      const index = values.indexOf(status)
      if (index > -1) {
        values.splice(index, 1)
      } else {
        values.push(status)
      }
      if (values.length > 0) {
        quickFilterMap.value.set('status', values.join(','))
      } else {
        quickFilterMap.value.delete('status')
      }
      emit('filter-changed')
    }

    const isPoMatchStatusSelected = (status: string) => {
      return selectedPoMatchStatuses.value.includes(status)
    }

    const togglePoMatchStatusFilter = (status: string) => {
      fullSearchStore.togglePoMatchStatus(status)
      emit('filter-changed')
    }

    const isAmountRangeSelected = (range: AmountRange) => {
      return selectedAmountRangeKey.value === range.key
    }

    const setAmountRange = (range: AmountRange) => {
      if (selectedAmountRangeKey.value === range.key) {
        // Deselect
        selectedAmountRangeKey.value = null
        fullSearchStore.setAmountRange(null, null)
        customAmountMin.value = null
        customAmountMax.value = null
      } else {
        selectedAmountRangeKey.value = range.key
        fullSearchStore.setAmountRange(range.from ?? null, range.to ?? null)
        customAmountMin.value = range.from ?? null
        customAmountMax.value = range.to ?? null
      }
      emit('filter-changed')
    }

    const applyCustomAmountRange = () => {
      selectedAmountRangeKey.value = null
      fullSearchStore.setAmountRange(customAmountMin.value, customAmountMax.value)
      emit('filter-changed')
    }

    const formatAmountRangeLabel = (range: AmountRange): string => {
      const hasFrom = typeof range.from === 'number'
      const hasTo = typeof range.to === 'number'

      if (!hasFrom && hasTo) {
        return `Under $${range.to.toLocaleString()}`
      }
      if (hasFrom && !hasTo) {
        return `Over $${range.from.toLocaleString()}`
      }
      if (hasFrom && hasTo) {
        return `$${range.from.toLocaleString()} - $${range.to.toLocaleString()}`
      }
      return range.key || 'All'
    }

    const formatDocTypeLabel = (value: string): string => {
      const settingsKey = 'pages.settings.' + value
      const fromSettings = i18n.t(settingsKey)
      if (fromSettings !== settingsKey) return fromSettings
      const lower = value.toLowerCase()
      const fromLower = i18n.t(lower)
      if (fromLower !== lower) return fromLower
      return value.toLowerCase().replace(/_/g, ' ').replace(/\b[a-z]/g, c => c.toUpperCase())
    }

    const clearAllFilters = () => {
      fullSearchStore.clearAllFilters()
      selectedAmountRangeKey.value = null
      customAmountMin.value = null
      customAmountMax.value = null
      showAllVendors.value = false
      emit('filter-changed')
    }

    return {
      facets,
      facetsLoading,
      selectedVendors,
      amountRange,
      selectedPoMatchStatuses,
      quickFilterMap,
      showAllVendors,
      vendorSearch,
      customAmountMin,
      customAmountMax,
      selectedAmountRangeKey,
      visibleVendors,
      allFacetsEmpty,
      hasActiveFilters,
      isDocTypeSelected,
      toggleDocTypeFilter,
      isVendorSelected,
      toggleVendorFilter,
      isStatusSelected,
      toggleStatusFilter,
      isPoMatchStatusSelected,
      togglePoMatchStatusFilter,
      isAmountRangeSelected,
      setAmountRange,
      applyCustomAmountRange,
      formatAmountRangeLabel,
      formatDocTypeLabel,
      clearAllFilters
    }
  }
})
</script>

