<template>
  <div>
    <!-- Start Date Input -->
    <div class="row q-my-sm capitalize">
      <span class="mt-10 q-mr-md">{{ $t('start_date') }}</span>
      <q-space />
      <q-input
        outlined
        dense
        v-model="startDate"
        :clearable="true"
        class="q-mr-sm"
        style="width: 227px; height: 40px"
        @update:model-value="modelUpdated()"
        data-cy="start-date-input"
      >
        <template v-slot:append>
          <q-icon name="event" class="cursor-pointer" data-cy="start-date-picker">
            <q-popup-proxy cover transition-show="scale" transition-hide="scale">
              <q-date v-model="startDate" mask="YYYY-MM-DD" @update:model-value="modelUpdated()">
                <div class="row items-center justify-end">
                  <q-btn v-close-popup label="Close" color="primary" flat />
                </div>
              </q-date>
            </q-popup-proxy>
          </q-icon>
        </template>
      </q-input>
    </div>

    <!-- End Date Input -->
    <div class="row q-my-sm capitalize">
      <span class="mt-10 q-mr-md">{{ $t('end_date') }}</span>
      <q-space />
      <q-input
        outlined
        dense
        v-model="endDate"
        :clearable="true"
        class="q-mr-sm"
        style="width: 227px; height: 40px"
        @update:model-value="modelUpdated()"
        data-cy="end-date-input"
      >
        <template v-slot:append>
          <q-icon name="event" class="cursor-pointer" data-cy="end-date-picker">
            <q-popup-proxy cover transition-show="scale" transition-hide="scale">
              <q-date v-model="endDate" mask="YYYY-MM-DD" @update:model-value="modelUpdated()">
                <div class="row items-center justify-end">
                  <q-btn v-close-popup label="Close" color="primary" flat />
                </div>
              </q-date>
            </q-popup-proxy>
          </q-icon>
        </template>
      </q-input>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia'
import { defineComponent, ref } from 'vue'
import { useFullSearchStore } from 'src/store/full-search.store'

export default defineComponent({
  name: 'DateRangeFilter',
  props: {
    start_date: {
      type: String,
      default: ''
    },
    end_date: {
      type: String,
      default: ''
    }
  },

  watch: {
    tempFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadFilters()
      }
    },
    startDate: {
      handler(newVal) {
        this.modelUpdated()
      }
    },
    endDate: {
      handler(newVal) {
        this.modelUpdated()
      }
    }
  },

  mounted() {
    this.loadFilters()
    // Only set from props if tempFilterMap is empty (first time opening)
    if (!this.tempFilterMap.has('date_range')) {
      this.startDate = this.start_date
      this.endDate = this.end_date
    }
  },

  methods: {
    loadFilters() {
      const dateRange = this.tempFilterMap.get('date_range')

      if (!dateRange) {
        this.startDate = ''
        this.endDate = ''
        return
      }

      // Parse comma-separated format: "2024-01-01,2024-12-31"
      const dates = dateRange.split(',')
      this.startDate = dates[0] || ''
      this.endDate = dates[1] || ''
    },

    modelUpdated() {
      // Store raw dates, backend will handle conversion
      if (this.startDate || this.endDate) {
        // Store dates as comma-separated string for simplicity
        const dateRange = `${this.startDate || ''},${this.endDate || ''}`
        this.tempFilterMap.set('date_range', dateRange)
      } else {
        this.tempFilterMap.delete('date_range')
      }
    }
  },

  setup() {
    const full_search_store = useFullSearchStore()
    const { tempFilterMap } = storeToRefs(full_search_store)

    return {
      tempFilterMap,
      startDate: ref(''),
      endDate: ref('')
    }
  }
})
</script>

<style scoped lang="scss">
.user-filter-select {
  width: 227px;
}

:deep(.q-field--dense .q-field__control) {
  height: 35px !important;
}
</style>
